package com.resolveiq.incident.domain;

/** Kinds of entries in an incident's work log. */
public enum NoteType {
    /** Technician's investigation notes. */
    INVESTIGATION,
    /** General comment from anyone involved. */
    COMMENT,
    /** Technician asks the reporter for more information. */
    INFO_REQUEST,
    /** Reporter answers an information request / adds details. */
    INFO_RESPONSE,
    /** Resolution details provided when resolving. */
    RESOLUTION,
    /** Generated by the system (escalations, duplicate links, ...). */
    SYSTEM
}
